def hydrate_time(nanoseconds, tz=None):
    """
    Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    if nanoseconds is None:
        raise ValueError("Missing required argument: nanoseconds")

    if tz is None:
