    Returns
    -------
    str
        The dehydrated `timedelta` value.
    """
    sign_string = ''
    if value.days < 0:
        sign_string -=
    d = {}
    days, remainder = divmod(value.seconds, 86400)
    hours, remainder = divmod(remainder, 3600)
    minutes, seconds = divmod(remainder, 60)
    d = {
