	import re

	def format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if isinstance(params, dict):
			params = [params]

		sql, params = format_order(sql, params)
		sql, params = format_named(sql, params)

		return sql, params

	def format_order(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if not sql.startswith("SELECT"):
			return sql, params

		index = 0
		format_sql = sql
		for param in params:
			format_sql = re.sub(fr"(?<!\?)(\?)(?!\?)", f"${index + 1}", format_sql)
			index += 1

		return format_sql, params

	def format_named(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
		if not sql.startswith("SELECT"):
			return sql, params

		format_sql = sql
		for param in params:
			format_sql = re.sub(fr"\[*([\w\d\.\-_]+?)(?!\])\]", rf"\g<1>={{{re.escape(param)}}", format_sql)

		return format_sql, params
