def try_retrieve_webfinger_document(self, handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    if not isinstance(handle, str):
        raise ValueError("Invalid handle type")

    host = handle.split("@")[1]
    resp = self._request_webfinger(host)
    if resp.status_code == requests.codes.NOT_FOUND:
        return None

    return resp.text

def _request_webfinger(self, host: str) -> requests.Response:
    url = f"{self.url_base}/webfinger?resource=acct:{quote(self.resource)}@{host}"
    return requests.get(url)

