def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """

    # Check if the key is already in the dictionary
    if key not in dic:
        # Initialize the key with a nested dictionary
        dic[key] = {}

    # Assign the value to the nested dictionary
    nested_dic = dic[key]
    for sub_key in keys:
        if sub_key not in nested_dic:
            nested_dic[sub_key] = {}
        nested_dic = nested_dic[sub_key]
    nested_dic[keys[-1]] = val

# Test cases:
assert dict_insert({}, 'val', 'key1.key2'.split('.')) == {'key1': {'key2': 'val'}}
assert dict_insert({}, 'val', 'key1'.split('.')) == {'key1': 'val'}
assert dict_insert({}, 'val', 'key1', ['key2', 'key3']) == {'key1': {'key2': {'key3': 'val'}}}
