def list_of_fully_qualified_file_names(directory, extension):
    """Return list of fully qualified file names in the given dir

    :param directory: directory to look for files
    :param extension: file extension to look for
    :return: list of fully qualified file names
    """
    try:
        return sorted([
            os.path.join(directory, fname)
            for fname in os.listdir(directory)
            if fname.endswith(extension)
        ])
    except OSError:
        return []

