    """Write ini file

    :param settings: name of the setting
    :param parent: parent setting
    :return: path to the ini file
    """
    try:
        ini = configparser.ConfigParser()
        ini.optionxform = str
        ini[''] = {}
        ini['']['setting'] = settings
        ini['']['parent'] = parent
        ini['']['values'] = kwargs
        with TemporaryFile("w+b") as temp:
            temp.write(ini.write().encode('utf-8'))
            temp.seek(0)
            return temp
    except OSError:
        return None

def write_json_file(obj, **kwargs):
    """Write json file

    :param obj: object to write as json
    :return: path to the json file
    """
    try:
        with TemporaryFile("w+b") as temp:
            json.dump(obj, temp)
            temp.seek(0)
            return temp
    except OSError:
        return None

