def _get_ansible_playbook(playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    # Create a Configuration object from the current workspace
    config = ir_workspace.get_configuration()

    # Override the verbosity level if specified
    if verbose is not None:
        config.verbosity = verbose

    # Override the extra variables if specified
    if extra_vars is not None:
        config.extra_vars = extra_vars

    # Override the ansible arguments if specified
    if ansible_args is not None:
        config.ansible_args = ansible_args

    # Create an AnsiblePlaybook instance from the configuration and playbook path
    return ansible_playbook.AnsiblePlaybook(config, playbook_path)

